begin;
alter policy cgf_document_upload on storage.objects with check(bucket_id='loan-documents' and exists(select 1 from public.loan_applications l where l.id::text=(storage.foldername(name))[1] and l.status in ('draft','docs_incomplete') and (public.cgf_is_super_admin() or (l.bank_id=public.current_user_bank_id() and public.current_user_role_code() in ('bank_admin','bank_officer')))));
alter policy cgf_document_cleanup on storage.objects using(bucket_id='loan-documents' and exists(select 1 from public.loan_applications l where l.id::text=(storage.foldername(name))[1] and l.status in ('draft','docs_incomplete') and (public.cgf_is_super_admin() or (l.bank_id=public.current_user_bank_id() and public.current_user_role_code() in ('bank_admin','bank_officer')))) and not exists(select 1 from public.loan_documents d where d.file_path=name));
alter policy cgf_document_insert_scope on public.loan_documents with check(uploaded_by=auth.uid() and exists(select 1 from public.loan_applications l where l.id=loan_id and l.status in ('draft','docs_incomplete') and (public.cgf_is_super_admin() or (l.bank_id=public.current_user_bank_id() and public.current_user_role_code() in ('bank_admin','bank_officer')))) and exists(select 1 from storage.objects o where o.bucket_id='loan-documents' and o.name=file_path and (storage.foldername(o.name))[1]=loan_id::text));
commit;
